sp_widget.client_script:
api.controller = function($scope) {

    var c = this;

    c.showPassword = false;
    c.loading = false;
    c.errorMessage = "";

    c.togglePassword = function() {
        c.showPassword = !c.showPassword;
    };

    c.login = function() {

        c.errorMessage = "";

        if (!c.data.student_id) {
            c.errorMessage = "Please enter your Student ID.";
            return;
        }

        if (!c.data.password) {
            c.errorMessage = "Please enter your password.";
            return;
        }

        c.loading = true;

        c.server.get({
            action: "login",
            student_id: c.data.student_id,
            password: c.data.password,
            remember: c.data.remember
        }).then(function(response) {

            c.loading = false;

            if (response.data.success) {
                window.location.href = "?id=cfms_home";
            } else {
                c.errorMessage =
                    response.data.message ||
                    "Invalid Student ID or password.";
            }

        }, function() {

            c.loading = false;
            c.errorMessage = "Unable to connect to the server.";

        });
    };

    c.forgotPassword = function() {
        window.location.href = "?id=forgot_password";
    };

    c.microsoftLogin = function() {
        alert("Microsoft Sign-In will be configured later.");
    };

    c.contactAdmin = function() {
        alert("Please contact your CFMS administrator.");
    };

    c.needHelp = function() {
        alert("Please contact the CFMS support team.");
    };

};

sp_widget.css:
/* ================================
   CFMS LOGIN PAGE
================================ */

.cfms-login-page {
  min-height: 100vh;
  width: 100%;
  background: #ffffff;
  color: #10222d;
  font-family: "Segoe UI", Arial, sans-serif;
  overflow: hidden;
}


/* ================================
   HEADER
================================ */

.cfms-header {
  height: 95px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 4.2%;
  background: #ffffff;
}


.cfms-logo-section {
  display: flex;
  align-items: center;
  gap: 15px;
}


.cfms-logo {
  width: 64px;
  height: 64px;
  border-radius: 50%;
  background: #1d9b4b;
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 27px;
  box-shadow: 0 5px 15px rgba(0,0,0,.12);
}


.logo-fork {
  margin-right: -4px;
}


.logo-spoon {
  margin-left: -4px;
}


.cfms-title {
  font-size: 42px;
  font-weight: 800;
  line-height: 40px;
  color: #10222d;
}


.cfms-subtitle {
  font-size: 18px;
  margin-top: 4px;
  color: #10222d;
}


.help-link {
  display: flex;
  align-items: center;
  gap: 10px;
  color: #006c3d;
  font-size: 17px;
  cursor: pointer;
}


.help-icon {
  width: 24px;
  height: 24px;
  border: 2px solid #50616a;
  border-radius: 50%;
  display: flex;
  justify-content: center;
  align-items: center;
  font-weight: bold;
}


/* ================================
   MAIN
================================ */

.cfms-main {
  display: flex;
  min-height: calc(100vh - 155px);
}


/* ================================
   HERO SECTION
================================ */

.hero-section {
  width: 55%;
  position: relative;
  overflow: hidden;
  background:
    linear-gradient(
      120deg,
      #ffffff 0%,
      #f8fcff 35%,
      #d9edfb 100%
    );
}


.hero-content {
  position: relative;
  z-index: 3;
  padding: 55px 8%;
}


.hero-tagline {
  position: absolute;
  top: -20px;
  right: 5%;
  color: #13783d;
  font-size: 27px;
  font-weight: 600;
  font-style: italic;
  line-height: 1.1;
}


.tagline-line {
  width: 105px;
  height: 3px;
  background: #168349;
  margin-left: 70px;
  margin-top: 6px;
}


.hero-content h1 {
  margin-top: 65px;
  font-size: 54px;
  line-height: 1.05;
  font-weight: 800;
  color: #102932;
  margin-bottom: 20px;
}


.hero-description {
  max-width: 520px;
  font-size: 23px;
  line-height: 1.4;
  color: #4d5960;
}


/* ================================
   FEATURES
================================ */

.feature-container {
  display: flex;
  justify-content: space-between;
  max-width: 600px;
  margin-top: 40px;
}


.feature {
  text-align: center;
  min-width: 105px;
}


.feature-icon {
  width: 70px;
  height: 70px;
  border-radius: 50%;
  background: #e7f7ed;
  color: #08743e;
  margin: auto;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 31px;
}


.feature-text {
  margin-top: 12px;
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
  color: #10222d;
}


/* ================================
   HERO IMAGE EFFECT
================================ */

.hero-image {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 47%;
  background:
    linear-gradient(
      to bottom,
      rgba(255,255,255,0),
      rgba(120,160,120,.20)
    );
}


.hero-image:after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(
      circle at 50% 90%,
      rgba(55,120,70,.35),
      transparent 55%
    );
}


/* building text */

.building-text {
  position: absolute;
  right: 12%;
  top: 25%;
  z-index: 2;
  font-size: 21px;
  font-weight: 600;
  color: #555e61;
  line-height: 1.4;
}


/* books */

.books {
  position: absolute;
  left: 8%;
  bottom: 8%;
  z-index: 4;
}


.books div {
  width: 200px;
  height: 30px;
  padding: 6px 12px;
  background: #ded7c5;
  border-bottom: 2px solid #a9a18e;
  font-size: 15px;
  font-weight: 600;
}


/* food quote */

.food-quote {
  position: absolute;
  left: 8%;
  bottom: 2%;
  z-index: 5;
  color: white;
  font-size: 23px;
  font-style: italic;
  font-family: Georgia, serif;
}


.food-quote div {
  width: 75px;
  height: 2px;
  background: white;
  margin-top: 5px;
}


/* ================================
   LOGIN SIDE
================================ */

.login-section {
  width: 45%;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 35px 6%;
  background:
    radial-gradient(
      circle at 0% 50%,
      #e7f5ff,
      #ffffff 55%
    );
}


.login-card {
  width: 100%;
  max-width: 560px;
  background: rgba(255,255,255,.92);
  border-radius: 25px;
  padding: 34px 48px;
  box-shadow:
    0 15px 50px rgba(0,0,0,.08);
}


/* ================================
   LOGIN ICON
================================ */

.login-icon {
  width: 105px;
  height: 105px;
  margin: 0 auto 12px;
  border-radius: 50%;
  background: #08743e;
  color: white;
  display: flex;
  justify-content: center;
  align-items: center;
  font-size: 47px;
  box-shadow: 0 10px 25px rgba(0,110,60,.25);
}


.login-card h2 {
  text-align: center;
  margin: 0;
  font-size: 32px;
  font-weight: 800;
  color: #0d1826;
}


.login-description {
  text-align: center;
  font-size: 17px;
  color: #4f5964;
  margin: 8px 0 30px;
}


/* ================================
   FORM
================================ */

.form-group {
  margin-bottom: 24px;
}


.form-group label {
  display: block;
  font-size: 17px;
  font-weight: 700;
  margin-bottom: 10px;
  color: #111c28;
}


.input-wrapper {
  position: relative;
}


.form-input {
  width: 100%;
  height: 56px;
  padding: 0 48px 0 61px;
  border: 1px solid #d2d9de;
  border-radius: 10px;
  background: white;
  font-size: 16px;
  outline: none;
  box-sizing: border-box;
  transition: .2s;
}


.form-input:focus {
  border-color: #08743e;
  box-shadow: 0 0 0 3px rgba(8,116,62,.10);
}


.input-icon {
  position: absolute;
  left: 18px;
  top: 50%;
  transform: translateY(-50%);
  font-size: 20px;
  z-index: 2;
}


.password-toggle {
  position: absolute;
  right: 15px;
  top: 50%;
  transform: translateY(-50%);
  border: none;
  background: transparent;
  font-size: 21px;
  color: #6b747a;
  cursor: pointer;
}


/* ================================
   OPTIONS
================================ */

.login-options {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin: 4px 0 22px;
}


.remember {
  display: flex;
  align-items: center;
  gap: 9px;
  font-size: 16px;
  color: #37414a;
  cursor: pointer;
}


.remember input {
  width: 22px;
  height: 22px;
  accent-color: #08743e;
}


.forgot-password {
  color: #006d3c;
  font-size: 16px;
  text-decoration: underline;
  cursor: pointer;
}


/* ================================
   LOGIN BUTTON
================================ */

.login-button {
  width: 100%;
  height: 58px;
  border: none;
  border-radius: 10px;
  background: #08743e;
  color: white;
  font-size: 19px;
  font-weight: 700;
  cursor: pointer;
  transition: .2s;
}


.login-button:hover {
  background: #065f32;
}


.login-button:disabled {
  opacity: .65;
  cursor: not-allowed;
}


.arrow {
  margin-left: 15px;
  font-size: 25px;
}


/* ================================
   ERROR
================================ */

.error-message {
  margin-top: 12px;
  padding: 10px;
  background: #fff0f0;
  color: #c62828;
  border-radius: 7px;
  text-align: center;
}


/* ================================
   DIVIDER
================================ */

.divider {
  display: flex;
  align-items: center;
  gap: 14px;
  margin: 25px 0;
}


.divider span {
  flex: 1;
  height: 1px;
  background: #dce1e5;
}


.divider label {
  color: #879098;
  font-size: 15px;
}


/* ================================
   MICROSOFT
================================ */

.microsoft-button {
  width: 100%;
  height: 57px;
  border: 1px solid #d2d8dd;
  background: white;
  border-radius: 10px;
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 13px;
  font-size: 17px;
  font-weight: 600;
  color: #17222b;
  cursor: pointer;
}


.microsoft-logo {
  display: grid;
  grid-template-columns: 9px 9px;
  grid-template-rows: 9px 9px;
  gap: 2px;
}


.microsoft-logo span:nth-child(1) {
  background: #f25022;
}


.microsoft-logo span:nth-child(2) {
  background: #7fba00;
}


.microsoft-logo span:nth-child(3) {
  background: #00a4ef;
}


.microsoft-logo span:nth-child(4) {
  background: #ffb900;
}


/* ================================
   ADMIN
================================ */

.admin-text {
  text-align: center;
  margin-top: 30px;
  color: #4d5660;
  font-size: 16px;
}


.admin-text a {
  color: #006d3c;
  text-decoration: underline;
  margin-left: 5px;
}


/* ================================
   FOOTER
================================ */

.cfms-footer {
  height: 60px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 4%;
  border-top: 1px solid #e6e9eb;
  background: white;
  color: #4f5962;
  font-size: 14px;
}


.footer-left,
.footer-middle,
.footer-right {
  display: flex;
  align-items: center;
  gap: 10px;
}


.footer-left strong {
  font-size: 18px;
  color: #10222d;
}


.leaf {
  font-size: 23px;
}


/* ================================
   RESPONSIVE
================================ */

@media screen and (max-width: 1100px) {

  .hero-content h1 {
    font-size: 42px;
  }

  .hero-description {
    font-size: 19px;
  }

  .login-card {
    padding: 30px;
  }

}


@media screen and (max-width: 850px) {

  .cfms-main {
    flex-direction: column;
  }

  .hero-section,
  .login-section {
    width: 100%;
  }

  .hero-section {
    min-height: 620px;
  }

  .login-section {
    padding: 40px 20px;
  }

  .cfms-footer {
    height: auto;
    padding: 20px;
    flex-direction: column;
    gap: 12px;
  }

}


@media screen and (max-width: 600px) {

  .cfms-header {
    height: 75px;
    padding: 0 20px;
  }

  .cfms-title {
    font-size: 27px;
  }

  .cfms-subtitle {
    font-size: 12px;
  }

  .cfms-logo {
    width: 48px;
    height: 48px;
  }

  .help-link {
    display: none;
  }

  .hero-content {
    padding: 35px 25px;
  }

  .hero-content h1 {
    font-size: 36px;
  }

  .hero-description {
    font-size: 17px;
  }

  .feature-container {
    flex-wrap: wrap;
    gap: 20px;
  }

  .login-card {
    padding: 25px 20px;
  }

}

